// Body stats (TP-1) — bodyweight and composition math the goals, the report
// card and the coach all read. Pulled out of body-measurements.js, which
// imports Firebase / AppState / ui-helpers and so can't be mirrored.
//
// Pure. Imports only mirrored siblings.
//
// MIRRORED: functions/body-stats.js is generated by
//   node scripts/sync-mirror.mjs js/core/features/body-stats.js functions/body-stats.js
// (tests/unit/movement-patterns-mirror.test.js enforces parity).

import { convertToUnit } from './coach-outcomes.js';

/**
 * 7-entry moving average at each point (the body-weight chart's line).
 * body-measurements.js re-exports this — it moved here unchanged.
 * @param {Array<{date: string, weight: number}>} entries - Sorted by date ascending
 * @returns {Array<{date: string, weight: number}>}
 */
export function calculate7DayAverage(entries) {
    if (!entries || entries.length === 0) return [];
    return entries.map((entry, i) => {
        const window = entries.slice(Math.max(0, i - 6), i + 1);
        const avg = window.reduce((sum, e) => sum + e.weight, 0) / window.length;
        return { date: entry.date, weight: Math.round(avg * 10) / 10 };
    });
}

const DAY = 86400000;
const toDay = (s) => new Date(`${s}T12:00:00`);
export function shiftDate(dateStr, n) {
    const d = toDay(dateStr);
    d.setDate(d.getDate() + n);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}
export const daysBetween = (a, b) => Math.round((toDay(b) - toDay(a)) / DAY);

/** A reading this far from the window's median is a bad weigh-in, not a trend. */
export const OUTLIER_SHARE = 0.03;

const round1 = (n) => Math.round(n * 10) / 10;

/** One reading per day (the latest that day), converted to `unit`, ascending. */
export function dailyWeights(entries = [], unit = 'lbs') {
    const byDate = new Map();
    for (const e of entries || []) {
        if (!e?.date || !(Number(e.weight) > 0)) continue;
        const prev = byDate.get(e.date);
        if (!prev || (e.timestamp || '') > (prev.timestamp || '')) byDate.set(e.date, e);
    }
    return [...byDate.values()]
        .sort((a, b) => a.date.localeCompare(b.date))
        .map(e => ({ date: e.date, weight: convertToUnit(e.weight, e.unit || 'lbs', unit) }));
}

/**
 * Bodyweight as a 7-day average ending `asOf` (calendar days, not the last 7
 * entries) — daily weigh-ins are noise. With 4+ readings in the window, a
 * reading more than OUTLIER_SHARE from the median is dropped first.
 * @returns {{value: number, readings: number, from: string, to: string}|null}
 */
export function weightAverage(entries, { asOf, days = 7, unit = 'lbs' } = {}) {
    if (!asOf) return null;
    const from = shiftDate(asOf, -(days - 1));
    let w = dailyWeights(entries, unit).filter(e => e.date >= from && e.date <= asOf).map(e => e.weight);
    if (!w.length) return null;
    if (w.length >= 4) {
        const sorted = [...w].sort((a, b) => a - b);
        const mid = sorted.length % 2 ? sorted[(sorted.length - 1) / 2] : (sorted[sorted.length / 2 - 1] + sorted[sorted.length / 2]) / 2;
        const kept = w.filter(x => Math.abs(x - mid) <= mid * OUTLIER_SHARE);
        if (kept.length) w = kept;
    }
    return { value: round1(w.reduce((s, x) => s + x, 0) / w.length), readings: w.length, from, to: asOf };
}

/** Lean mass of a scan in `unit` (scans carry massUnit or unit; lbs by default). */
export function scanLeanMass(scan, unit = 'lbs') {
    const v = scan?.totalLeanMass ?? (typeof scan?.leanMass === 'number' ? scan.leanMass : null);
    if (v == null) return null;
    return convertToUnit(v, scan.massUnit || scan.unit || 'lbs', unit);
}

/** Body-fat percentage of a scan. */
export function scanBodyFatPct(scan) {
    const v = Number(scan?.totalBodyFat);
    return Number.isFinite(v) && v > 0 ? round1(v) : null;
}

/** Scans on or before `asOf`, newest first. */
export function scansAsOf(scans = [], asOf) {
    return (scans || []).filter(s => s?.date && (!asOf || s.date <= asOf)).sort((a, b) => b.date.localeCompare(a.date));
}
